95,"seed":916630798},{"x":63.824812530917406,"y":28.085254909352205,"kind":"rock","rot":187,"seed":829461773}]}}},"turn_limit":6}}]$tables$::jsonb) loop
    insert into missions (id, name, mode, game_sizes, composition, common_objectives, secondary_objectives, battle_march,
      special_rules, objective_vp, custom_objective_ids, terrain, turn_limit, campaign_id, created_by)
    select x.id, x.name, x.mode, x.game_sizes, x.composition, x.common_objectives, x.secondary_objectives, x.battle_march,
      x.special_rules, x.objective_vp, x.custom_objective_ids, x.terrain, x.turn_limit, v_campaign.id, v_campaign.created_by
    from jsonb_populate_record(null::missions, r -> 'mission') x
    on conflict (id) do update set name = excluded.name, mode = excluded.mode, game_sizes = excluded.game_sizes,
      composition = excluded.composition, common_objectives = excluded.common_objectives,
      secondary_objectives = excluded.secondary_objectives, battle_march = excluded.battle_march,
      special_rules = excluded.special_rules, objective_vp = excluded.objective_vp,
      custom_objective_ids = excluded.custom_objective_ids, terrain = excluded.terrain, turn_limit = excluded.turn_limit;
    v_tables := v_tables || jsonb_build_object(r ->> 'area', r -> 'mission' ->> 'id');
  end loop;

  update campaigns
  set settings = jsonb_set(settings, '{warcastle}', coalesce(settings -> 'warcastle', '{}'::jsonb) || jsonb_build_object('tables', coalesce(settings -> 'warcastle' -> 'tables', '{}'::jsonb) || v_tables))
  where id = v_campaign.id;

  raise notice 'WarCastle: % tables set.', (select count(*) from jsonb_object_keys(v_tables));
end $do$;
